int calcularGrupo(std::array<int, 3> grupo) {
    // Construye aqui la suma de los aportes de este grupo.
    // Cada positivo aporta el doble; los demas aportan cero.
    return grupo[0];
}

int main() {
    std::array<std::array<int, 3>, 2> grupos{};
    for (std::size_t fila = 0; fila < grupos.size(); ++fila) {
        for (std::size_t i = 0; i < grupos[fila].size(); ++i) {
            if (!(std::cin >> grupos[fila][i]) ||
                grupos[fila][i] < -100 || grupos[fila][i] > 100) {
                std::cout << "Datos invalidos\n";
                return 0;
            }
        }
    }

    int totalLote = 0;
    for (std::size_t fila = 0; fila < grupos.size(); ++fila) {
        const int resultado = calcularGrupo(grupos[fila]);
        std::cout << "Grupo " << fila << ": " << resultado << '\n';
        totalLote += resultado;
    }
    std::cout << "Total: " << totalLote << "\nOriginal\n";
    for (std::size_t fila = 0; fila < grupos.size(); ++fila) {
        for (std::size_t i = 0; i < grupos[fila].size(); ++i) {
            if (i != 0) {
                std::cout << ' ';
            }
            std::cout << grupos[fila][i];
        }
        std::cout << '\n';
    }
    return 0;
}

