#include <array>
#include <cstddef>
#include <iostream>

int calcularGrupo(std::array<int, 3> grupo) {
    int total = 0;
    for (std::size_t i = 0; i < grupo.size(); ++i) {
        int aporte = 0;
        if (grupo[i] > 0) {
            aporte = grupo[i] * 2;
        }
        total += aporte;
    }
    return total;
}

